"""Persistent reservation controller for protocol version 3.0.0.

The controller owns the graph image, the lease book, proposal history and the
revision counter.  Compilation and negative certificates live in compiler.py.
Every number that reaches an admission decision is an exact Python integer.
"""

import re

import compiler
from compiler import find_deficient_cut

LIM = 10 ** 12
ID_RE = re.compile(r'[A-Za-z0-9_.\-]{1,32}\Z')


class Invalid(Exception):
    pass


# ---------------------------------------------------------------- validation

def _int(x, lo=0, hi=LIM):
    if type(x) is not int or x < lo or x > hi:
        raise Invalid()
    return x


def _name(x):
    if not isinstance(x, str) or not ID_RE.match(x):
        raise Invalid()
    return x


def _window(x):
    if not isinstance(x, list) or len(x) != 2:
        raise Invalid()
    s = _int(x[0])
    e = _int(x[1])
    if not s < e:
        raise Invalid()
    return (s, e)


def _envelope(x):
    if not isinstance(x, list) or len(x) > 128:
        raise Invalid()
    out = {}
    for item in x:
        if not isinstance(item, list) or len(item) != 2:
            raise Invalid()
        l = _int(item[0], 0, 127)
        rate = _int(item[1], 1, LIM)
        if l in out:
            raise Invalid()
        out[l] = rate
    return out


